static uint8_t retained[50000],sent[LS_MAX_EVENT_SIZE];static size_t sent_length;
static int equal_hex(const uint8_t *data,const char *hex,size_t length){static const char digits[]="0123456789abcdef";for(size_t i=0;i<length;i++)if(digits[data[i]>>4]!=hex[i*2]||digits[data[i]&15]!=hex[i*2+1])return 0;return 1;}
static bool available(void *x){(void)x;return true;}static size_t mtu(void *x){(void)x;return LS_MAX_EVENT_SIZE;}static ls_result_t send_data(void *x,const uint8_t *data,size_t length){(void)x;memcpy(sent,data,length);sent_length=length;return LS_OK;}
static ls_result_t random_bytes(void *context,uint8_t *output,size_t length){uint32_t *state=(uint32_t *)context;for(size_t i=0;i<length;i++){*state=*state*1664525u+1013904223u;output[i]=(uint8_t)(*state>>24);}return LS_OK;}
